-- GenDB engine variant Q04-always_true_conjunct: template q04.sql, kind always_true_conjunct (generated by generate.py; frozen)
SELECT
  o_orderpriority,
  COUNT(*) AS order_count
FROM orders
WHERE
  o_orderdate >= $1
  AND o_orderdate < $1 + INTERVAL '3 MONTH'
  AND EXISTS(
    SELECT
      *
    FROM lineitem
    WHERE
      l_orderkey = o_orderkey AND l_commitdate < l_receiptdate
  )
  AND o_orderkey = o_orderkey
GROUP BY
  o_orderpriority
ORDER BY
  o_orderpriority
